@FunctionalInterface
interface Subscriber {
    void onMessage(String topic, Object payload) throws Exception;
}

// Immutable value object — Java record
record Message(String topic, Object payload, long timestamp) {
    public static Message of(String topic, Object payload) {
        return new Message(topic, payload, System.currentTimeMillis());
    }
}

class Subscription {
    private static final int MAX_RETRIES = 3;

    private final String subscriptionId;
    private final String topic;
    private final Subscriber subscriber;
    private final BlockingQueue<Message> queue;
    private final Thread worker;
    private final AtomicLong dropped = new AtomicLong();
    private volatile boolean running = true;

    public Subscription(String topic, Subscriber sub, int capacity) {
        this.subscriptionId = UUID.randomUUID().toString();
        this.topic = topic;
        this.subscriber = sub;
        this.queue = new ArrayBlockingQueue<>(capacity);
        this.worker = new Thread(this::run,
            "pubsub-worker-" + subscriptionId.substring(0, 8));
        this.worker.setDaemon(true);
        this.worker.start();
    }

    // ── enqueue (called by publisher, non-blocking) ──
    public void enqueue(Message msg) {
        if (!running) return;

        // Try to add — if full, drop oldest and retry once
        if (!queue.offer(msg)) {
            queue.poll();                   // drop oldest
            dropped.incrementAndGet();
            queue.offer(msg);               // best-effort — may race but ok
        }
    }

    // ── Worker loop ──────────────────────
    private void run() {
        while (running) {
            try {
                Message msg = queue.take();  // blocks until message or interrupt
                deliverWithRetry(msg);
            } catch (InterruptedException e) {
                if (!running) break;
                Thread.currentThread().interrupt();
            }
        }
    }

    // ── At-least-once delivery with retry ──
    private void deliverWithRetry(Message msg) {
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            try {
                subscriber.onMessage(msg.topic(), msg.payload());
                return;  // success
            } catch (Exception e) {
                if (attempt == MAX_RETRIES - 1) {
                    dropped.incrementAndGet();
                    // log: "Subscriber " + subscriptionId + " dropped after " + MAX_RETRIES + " retries"
                }
                // Backoff could be added here
            }
        }
    }

    public void stop() {
        running = false;
        worker.interrupt();
        // Optional: drain remaining messages before exit
    }

    public String getSubscriptionId() { return subscriptionId; }
    public String getTopic() { return topic; }
    public long getDroppedCount() { return dropped.get(); }
}

class PubSubBroker {
    private final ConcurrentHashMap<String, CopyOnWriteArrayList<Subscription>>
        topicSubscriptions = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Subscription>
        allSubscriptions = new ConcurrentHashMap<>();
    private final int queueCapacity;
    private volatile boolean running = true;

    public PubSubBroker(int queueCapacity) {
        this.queueCapacity = queueCapacity;
    }

    // ── publish (non-blocking, O(subscribers)) ──
    public void publish(String topic, Object payload) {
        if (topic == null) throw new IllegalArgumentException("topic required");
        if (!running) throw new IllegalStateException("Broker stopped");

        List<Subscription> subs = topicSubscriptions.get(topic);
        if (subs == null || subs.isEmpty()) return;  // no subscribers, drop

        Message msg = Message.of(topic, payload);
        // CopyOnWriteArrayList allows concurrent iteration during add/remove
        for (Subscription sub : subs) {
            sub.enqueue(msg);  // non-blocking, may drop internally
        }
    }

    // ── subscribe ────────────────────────
    public String subscribe(String topic, Subscriber subscriber) {
        if (topic == null || subscriber == null)
            throw new IllegalArgumentException();
        if (!running) throw new IllegalStateException("Broker stopped");

        Subscription sub = new Subscription(topic, subscriber, queueCapacity);

        topicSubscriptions
            .computeIfAbsent(topic, k -> new CopyOnWriteArrayList<>())
            .add(sub);
        allSubscriptions.put(sub.getSubscriptionId(), sub);

        return sub.getSubscriptionId();
    }

    // ── unsubscribe ──────────────────────
    public void unsubscribe(String handle) {
        Subscription sub = allSubscriptions.remove(handle);
        if (sub == null) return;  // already removed or unknown

        List<Subscription> list = topicSubscriptions.get(sub.getTopic());
        if (list != null) list.remove(sub);

        sub.stop();
    }

    // ── Graceful shutdown ────────────────
    public void shutdown() {
        running = false;
        allSubscriptions.values().forEach(Subscription::stop);
        allSubscriptions.clear();
        topicSubscriptions.clear();
    }
}

PubSubBroker broker = new PubSubBroker(1000);

// Subscriber 1 — fast consumer
String h1 = broker.subscribe("orders", (topic, payload) -> {
    System.out.println("Fast: " + payload);
});

// Subscriber 2 — slow consumer (won't block fast one)
String h2 = broker.subscribe("orders", (topic, payload) -> {
    Thread.sleep(100);  // simulated slow processing
    System.out.println("Slow: " + payload);
});

// Publish 1000 messages — returns immediately
for (int i = 0; i < 1000; i++) {
    broker.publish("orders", "order-" + i);
}

// Fast subscriber processes all 1000 quickly
// Slow subscriber processes at 10/sec, may drop messages if queue fills

broker.unsubscribe(h2);
broker.shutdown();
